proc sort data=ar_ret nodupkey; by infocode year eps_rdate; run;
proc datasets library=work NOLIST; delete ar_ret1 - ar_ret3; quit;
proc export data=ar_ret replace outfile= "&path.\Data\annual_report_all_events.dta"; run;

proc import datafile="&path.\Data\quarterly_dataset_processed.dta" out=data_qtr dbms = dta replace; run;
Data ds_mf1; set data_qtr (keep=isin dscd date year qtr country_txt industry_cam); if dscd^=""; run;
Data ds_mf2(drop=date year qtr); Set ds_mf1; begin_date = date;
	if qtr = 1 then end_date = mdy(3,31,year);
	if qtr = 2 then end_date = mdy(6,30,year);
	if qtr = 3 then end_date = mdy(9,30,year);
	if qtr = 4 then end_date = mdy(12,31,year);
run;
Proc sql; create table weekly_returns as select distinct *
	from weekly_ret_dscode a 
	left join ds_mf2 b on (a.dscd = b.dscd) AND (a.date >= b.begin_date) AND (a.date <= b.end_date)
	having country_txt^=""; quit;
proc datasets library=work; delete weekly_ret ds_mf2 ds_mf1 data_qtr; run;

/*Build Portfolios based on Industry - Country*/
Proc sort data=weekly_returns out=OAM1; by dscd date; run;
Data OAM2; Set OAM1; dscd_L1 = lag1(dscd); mv_usd_L1 = lag1(mv_usd); If dscd ne dscd_L1 then do; mv_usd_L1 = .; end; run;
Data OAM3; Set OAM2; week_nr = week(week); weekyear = (year * 100) + week_nr; If missing(industry_cam) then delete; If missing(ret) = 1 then ret = 0; run;
proc export data=OAM3 outfile= "&path.\Data\weekly_returns_processed.dta" REPLACE; run;

proc import datafile= "&path.\Data\analysis_sample_annual_events.dta" dbms=dta replace out=ar_dates_long_1; run;
Proc sql; create table ar_dates_long_2 as select distinct a.*, b.dscd as peer_dscd label="peer_dscd", b.focal_event_date as peer_event_date label="peer_event_date"
	from ar_dates_long_1 a
	left join ar_dates_long_1 b on (a.dscd^=b.dscd & year(a.yearqtr)=year(b.yearqtr) & a.country=b.country & a.industry_cam=b.industry_cam);
data ar_dates_long_3; set ar_dates_long_2(drop=country_txt); if intnx('month',focal_event_date,-1,'s')<=peer_event_date<=intnx('month',focal_event_date,1,'s') & dscd^=peer_dscd then delete; run;
proc sql; create table ar_dates_long_4 as select distinct a.*, b.mdate, b.ret as peer_ret,	b.exchintcode as peer_exchintcode
	from ar_dates_long_3 a
	left join Ds_overview_pricing b
		on b.dscode=a.peer_dscd & intnx('month',a.focal_event_date,-1,'s')<=b.mdate<=intnx('WEEKDAY',a.focal_event_date,10,'s');
proc sql; create table ar_dates_long_5 as select distinct a.*, c.ret as focal_ret, c.exchintcode
	from ar_dates_long_4 a
	left join Ds_overview_pricing c
		on c.dscode=a.dscd & a.mdate=c.mdate;
data ar_dates_long_6; set ar_dates_long_5;
	if mdate<=intnx('WEEKDAY',focal_event_date,10,'s') & mdate>=intnx('WEEKDAY',focal_event_date,-1,'s') then ar10=1; else ar10=0;
	if ar10>0;
run;
proc sql; create table ar_dates_long_7 as select distinct *,
	sum(ar10) as trading_days_ar10_peer,
	sum(ar10) as trading_days_ar10_focal
	from ar_dates_long_6
	group by dscd, focal_event_date, peer_dscd, exchintcode;
proc datasets library=work NOLIST; delete ar_dates_long_1 - ar_dates_long_5; quit;
proc export data=ar_dates_long_7 replace outfile= "&path.\Data\annual_events_1.dta"; run;

/*Creating peer and focal firm returns*/
proc sql; create table ar_dates_long_7 as select distinct dscd, exchintcode, yearqtr, focal_event_date, peer_dscd, peer_event_date,
	sum(ar10) as trading_days_ar10_peer,
	sum(ar10) as trading_days_ar10_focal
	from ar_dates_long_6
	group by dscd, focal_event_date, peer_dscd, exchintcode;
proc sql; create table ar_dates_long_8 as select distinct a.*, 
		intnx('week',focal_event_date,1,'b') as weekyear, weekday(focal_event_date) as weekday,
	 	max(trading_days_ar10_focal) as max_trading_days_ar10_focal
	from ar_dates_long_7 a
	group by dscd, focal_event_date, exchintcode
	having trading_days_ar10_peer>0;
data ar_dates_long(drop= max_trading_days_ar10_focal); set ar_dates_long_8; if weekday=1 then weekday=8; weekday=weekday-1;
	if max_trading_days_ar10_focal^=trading_days_ar10_focal then do; trading_days_ar10_focal=.; end;
	if peer_dscd="" then delete; run;
proc sort data=ar_dates_long nodupkey; by dscd yearqtr focal_event_date peer_dscd; run;
proc datasets library=work NOLIST; delete ar_dates_long_7 - ar_dates_long_8; quit;
proc export data=ar_dates_long replace outfile= "&path.\Data\annual_events_2.dta"; run;

