/*weighted average exchange rates*/
proc sql; create table FX_2 as select distinct a.exrateintcode, a.exratedate, a.fromcurrcode, a.midrate, avg(c.midrate) as midrate_qtr from FX_1 a  
	left join FX_1 c on a.exrateintcode=c.exrateintcode & intnx('qtr',a.exratedate,-1,'s')<c.exratedate<=a.exratedate 
	where a.exratedate>'01jan1989'd group by a.exrateintcode, a.exratedate; 
create table FX_3 as select distinct a.*, avg(b.midrate) as midrate_month from FX_2 a 
	left join FX_1 b on a.exrateintcode=b.exrateintcode & intnx('month',a.exratedate,-1,'s')<b.exratedate<=a.exratedate
	group by a.exrateintcode, a.exratedate;
proc sql; create table FX_4 as select distinct a.*, avg(b.midrate) as midrate_year from FX_3 a 
	left join FX_1 b on a.exrateintcode=b.exrateintcode & intnx('year',a.exratedate,-1,'s')<b.exratedate<=a.exratedate
	group by a.exrateintcode, a.exratedate 
	having exratedate>'01jan1990'd 
	order by a.exrateintcode,  exratedate desc;
quit;
data FX_5; set FX_4; by exrateintcode;
      save_date = exratedate; prev_date=lag(exratedate);  diff = save_date - prev_date;
      DROP save_date prev_date diff;
      if first.exrateintcode then output;
      else do;
         if diff <= -2 then do;
               do exratedate = prev_date -1  to save_date by -1;
                    output;
               end;
        end; else output;
   end;
run;
proc sort data= FX_5 out=FX_&currency; by exrateintcode exratedate; run;

