/*Merge country, exchange and number of shares*/
proc sql; create table del3 as select distinct a.nr, a.InfoCode, case when e.DsCode is not null then e.DsCode else d.altDsCode  end as DsCode, a.MarketDate, 
	datepart(a.marketdate) as mdate format date9., intnx('month',datepart(a.marketdate),0,'b') as yearmonth format yymms10., a.ExchIntCode, d.IsPrimExchQt, 
	a.isocurrcode as Currency, a.ri, c.ExchName length=30, c.exchctrycode, 
	case when d.PriceUnit = 'E-02' then a.Close_/100 else a.Close_ end as Close_, case when d.PriceUnit = 'E-02' then a.bid/100 else a.bid end as Bid, 
	case when d.PriceUnit = 'E-02' then a.ask/100 else a.ask end as Ask, a.volume,
	f.numshrs
	from del a
	left join qa.ds2Exchange c on a.ExchIntCode=c.ExchIntCode
	left join qa.ds2exchqtinfo d on a.InfoCode = d.InfoCode and a.ExchIntCode = d.ExchIntCode
	left join qa.ds2ctryqtinfo e on	a.InfoCode = e.InfoCode
	left join del2 f on a.infocode=f.infocode & f.begdate<=datepart(a.marketdate)<=f.enddate
	where datepart(a.marketdate)>='01jan2000'd
	having c.ExchCtryCode in ("AL", "AD", "AT", "BY", "BE", "BA", "BG", "HR", "CY",	"CZ", "DK", "EE", "FO", "FI", "FR", "DE", "GI", "GR", "HU",	"IS", "IE", "IM", "IT", "RS", "LV", "LI", "LT", "LU", "MK", "MT", "MD", "MC","ME", 	"NL", "NO", "PL", "PT", "RO", "RU", "SM", "RS", "SK", "SI", "ES", "SE", "CH", "UA", "GB", "VA", "RS"); 
	;
	create table del4 as select InfoCode, AdjType, adjDate, coalesce(endAdjDate,'01jan3000:00:00:00'dt) as endAdjDate, CumAdjFactor 
	from qa.ds2adj 
	union all select InfoCode, 0 as AdjType, min(adjDate) as adjDate, '01jan3000:00:00:00'dt as endAdjDate, 1 as CumAdjFactor 
		from qa.ds2adj

